CREATE DATABASE IF NOT EXISTS alumniconnect CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE alumniconnect;
CREATE TABLE departments(department_id INT AUTO_INCREMENT PRIMARY KEY,department_name VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE alumni(alumni_id INT AUTO_INCREMENT PRIMARY KEY,first_name VARCHAR(60) NOT NULL,last_name VARCHAR(60) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,phone VARCHAR(25),location VARCHAR(120),department_id INT NOT NULL,graduation_year SMALLINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(department_id) ON UPDATE CASCADE ON DELETE RESTRICT,CHECK(graduation_year BETWEEN 1950 AND 2100),INDEX(graduation_year),INDEX(department_id),INDEX(location)) ENGINE=InnoDB;
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('ADMIN','ALUMNI') NOT NULL DEFAULT 'ALUMNI',alumni_id INT UNIQUE,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(alumni_id) REFERENCES alumni(alumni_id) ON UPDATE CASCADE ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE education(education_id INT AUTO_INCREMENT PRIMARY KEY,alumni_id INT NOT NULL,degree VARCHAR(100) NOT NULL,institution VARCHAR(150) NOT NULL,field_of_study VARCHAR(120),enrollment_year SMALLINT NOT NULL,graduation_year SMALLINT NOT NULL,FOREIGN KEY(alumni_id) REFERENCES alumni(alumni_id) ON DELETE CASCADE ON UPDATE CASCADE,CHECK(graduation_year>=enrollment_year),INDEX(alumni_id)) ENGINE=InnoDB;
CREATE TABLE companies(company_id INT AUTO_INCREMENT PRIMARY KEY,company_name VARCHAR(150) NOT NULL UNIQUE,industry VARCHAR(100),location VARCHAR(120),INDEX(industry)) ENGINE=InnoDB;
CREATE TABLE career_history(career_id INT AUTO_INCREMENT PRIMARY KEY,alumni_id INT NOT NULL,company_id INT NOT NULL,designation VARCHAR(150) NOT NULL,job_location VARCHAR(120),start_date DATE NOT NULL,end_date DATE,is_current BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(alumni_id) REFERENCES alumni(alumni_id) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY(company_id) REFERENCES companies(company_id) ON DELETE RESTRICT ON UPDATE CASCADE,CHECK(end_date IS NULL OR end_date>=start_date),INDEX(alumni_id),INDEX(company_id),INDEX(job_location)) ENGINE=InnoDB;
CREATE TABLE skills(skill_id INT AUTO_INCREMENT PRIMARY KEY,skill_name VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE alumni_skills(alumni_id INT NOT NULL,skill_id INT NOT NULL,skill_level ENUM('Beginner','Intermediate','Advanced','Expert') DEFAULT 'Intermediate',PRIMARY KEY(alumni_id,skill_id),FOREIGN KEY(alumni_id) REFERENCES alumni(alumni_id) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY(skill_id) REFERENCES skills(skill_id) ON DELETE RESTRICT ON UPDATE CASCADE,INDEX(skill_id)) ENGINE=InnoDB;
CREATE TABLE mentorship(mentorship_id INT AUTO_INCREMENT PRIMARY KEY,alumni_id INT NOT NULL UNIQUE,is_available BOOLEAN NOT NULL DEFAULT FALSE,domain VARCHAR(150),topics TEXT,availability_details VARCHAR(255),updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(alumni_id) REFERENCES alumni(alumni_id) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE OR REPLACE VIEW alumni_directory_view AS SELECT a.alumni_id,CONCAT(a.first_name,' ',a.last_name) full_name,a.email,a.location,a.graduation_year,d.department_name,co.company_name,ch.designation,co.industry,EXISTS(SELECT 1 FROM mentorship m WHERE m.alumni_id=a.alumni_id AND m.is_available=1) mentorship_available FROM alumni a LEFT JOIN departments d ON a.department_id=d.department_id LEFT JOIN career_history ch ON a.alumni_id=ch.alumni_id AND ch.is_current=1 LEFT JOIN companies co ON ch.company_id=co.company_id;
